const raw = $input.item.json || {};
const extracted = raw.extracted_params || {};

const project_id = raw.project_id || extracted.project_id || null;
const project_name = raw.project_name || 'Active Anime Project';
const episode_no = Number(raw.episode_no || raw.episode_number || extracted.episode_number || 1);
const season_no = Number(raw.season_no || raw.season_number || raw.current_season || extracted.season_no || 1);

const script_text = (raw.script_text || raw.script || '').toString().trim();
const scenes = Array.isArray(raw.scenes) ? raw.scenes : (Array.isArray(raw.script_json?.scenes) ? raw.script_json.scenes : []);
const user_prompt = (raw.user_prompt || raw.userPrompt || raw.rawText || `Verify continuity for Episode ${episode_no}`).toString().trim();
const sessionId = (raw.sessionId || `sess_${$execution.id}`).toString();
const caller_workflow = (raw.caller_workflow || (script_text || scenes.length > 0 ? 'WF-02' : 'WF-00')).toString();

if (!project_id) {
  throw new Error('WF-06 Error: project_id is strictly required for Continuity Evaluation (Rule 5 Project Isolation).');
}

const hasContentPayload = Boolean(script_text.length > 0 || scenes.length > 0);
const evaluation_mode = hasContentPayload ? 'CONTENT_VALIDATION' : 'PREFLIGHT_READINESS';

return {
  json: {
    ...raw, project_id, project_name, episode_no, episode_number: episode_no, season_no, season_number: season_no,
    script_text, scenes, user_prompt, sessionId, caller_workflow, evaluation_mode
  }
};

const base = $('Input Normalizer & Scope Resolver').first().json;

function unpackRows(nodeName, requiredField) {
  try {
    const rawItems = $(nodeName).all().map(i => i.json);
    const rows = [];
    for (const entry of rawItems) {
      if (Array.isArray(entry)) {
        for (const r of entry) { if (r && (!requiredField || r[requiredField] !== undefined)) rows.push(r); }
      } else if (entry && (!requiredField || entry[requiredField] !== undefined)) { rows.push(entry); }
    }
    return rows;
  } catch (e) { return []; }
}

const projectRows = unpackRows('Supabase: Fetch Project & Bible', 'id');
const projectRec = projectRows[0] || {};
const storyBible = projectRec.story_bible || {};
const resolvedSeason = Number(projectRec.current_season || base.season_no || 1);

const canonFacts = unpackRows('Supabase: Fetch Canon Facts', 'fact_key');
const snapshots = unpackRows('Supabase: Fetch Story State Snapshot', 'snapshot_data');
const latestSnapshot = snapshots[0] ? snapshots[0].snapshot_data : null;
const charStatuses = unpackRows('Supabase: Fetch Character Status', 'character_code');
const timelineEvents = unpackRows('Supabase: Fetch Story Timeline', 'event_description');
const storyRules = unpackRows('Supabase: Fetch Story Rules', 'rule_code');
const mysteries = unpackRows('Supabase: Fetch Mystery Tracker', 'description');

const deterministicViolations = [];
const statusByChar = {};
const deadCharacters = new Set();

for (const cs of charStatuses) {
  const code = (cs.character_code || '').toString().toUpperCase().trim();
  const st = (cs.status || 'alive').toString().toLowerCase().trim();
  if (!code) continue;
  statusByChar[code] = { status: st, status_changed_ep: Number(cs.status_changed_ep || 0) };
  if (st === 'dead' || st === 'deceased') { deadCharacters.add(code); }
}

if (latestSnapshot && latestSnapshot.world_state && typeof latestSnapshot.world_state === 'object') {
  const wsStatuses = latestSnapshot.world_state.character_statuses || {};
  for (const [k, v] of Object.entries(wsStatuses)) {
    const code = k.toUpperCase().trim();
    const st = (v || '').toString().toLowerCase().trim();
    if (st === 'dead' || st === 'deceased') { deadCharacters.add(code); statusByChar[code] = { status: 'dead', status_changed_ep: latestSnapshot.episode_id }; }
  }
}

const lastLocationByChar = {};
for (const ev of timelineEvents) {
  const loc = (ev.location || '').toString().toUpperCase().trim();
  if (!loc) continue;
  const parts = Array.isArray(ev.characters_involved) ? ev.characters_involved : (typeof ev.characters_involved === 'string' ? ev.characters_involved.split(',') : []);
  for (const p of parts) {
    const code = p.toString().toUpperCase().trim();
    if (code && !lastLocationByChar[code]) { lastLocationByChar[code] = { location: loc, episode_no: ev.episode_no, event_code: ev.event_code }; }
  }
}

const flashbackRegex = /\b(flashback|memory|past\s+vision|dream\s+sequence|hallucination|yaad|ateet|purani\s+yaad)\b/i;
const travelTransitionRegex = /\b(travel|portal|teleport|arrive|journey|train|flight|walked|reached|timeskip|next\s+day|drove|flew|ship|gate)\b/i;
const runningLocationByChar = { ...lastLocationByChar };

for (let i = 0; i < base.scenes.length; i++) {
  const sc = base.scenes[i] || {};
  const sceneOrder = Number(sc.scene_order || (i + 1));
  const speaker = (sc.dialogue_speaker_id || '').toString().toUpperCase().trim();
  const sceneLoc = (sc.location_code || '').toString().toUpperCase().trim();
  const combinedSceneText = `${sc.visual_prompt || sc.description || ''} ${sc.action_summary || ''} ${sc.voice_text || ''}`;
  const isFlashback = Boolean(sc.is_flashback === true || flashbackRegex.test(combinedSceneText));

  if (speaker && deadCharacters.has(speaker) && !isFlashback) {
    deterministicViolations.push({ type: 'STATUS_VIOLATION', severity: 'CRITICAL', description: `Deterministic Guard: Dead character ${speaker} has active dialogue/action in Scene ${sceneOrder} without an explicit flashback flag.`, entities_involved: [speaker, `SCENE_${sceneOrder}`], suggested_fix: `Mark Scene ${sceneOrder} as a flashback or remove ${speaker}.` });
  }

  for (const deadCode of deadCharacters) {
    if (deadCode !== speaker && new RegExp(`\\b${deadCode}\\b`, 'i').test(combinedSceneText) && !isFlashback) {
      deterministicViolations.push({ type: 'STATUS_VIOLATION', severity: 'CRITICAL', description: `Deterministic Guard: Dead character ${deadCode} appears in Scene ${sceneOrder} outside of a flashback.`, entities_involved: [deadCode, `SCENE_${sceneOrder}`], suggested_fix: `Convert Scene ${sceneOrder} to a flashback sequence.` });
    }
  }

  if (speaker && speaker !== 'NARRATOR' && sceneLoc && !isFlashback) {
    const prevLocObj = runningLocationByChar[speaker];
    if (prevLocObj && prevLocObj.location && prevLocObj.location !== sceneLoc) {
      const hasTravelCue = travelTransitionRegex.test(combinedSceneText);
      if (!hasTravelCue) {
        deterministicViolations.push({ type: 'STATUS_VIOLATION', severity: 'WARNING', description: `Deterministic Location Guard: Character ${speaker} jumped from ${prevLocObj.location} to ${sceneLoc} without a travel transition.`, entities_involved: [speaker, prevLocObj.location, sceneLoc], suggested_fix: `Add a travel transition for ${speaker}.` });
      }
    }
    runningLocationByChar[speaker] = { location: sceneLoc, episode_no: base.episode_no, event_code: sceneOrder };
  }
}

const textToInspect = `${base.script_text || ''}\n${base.user_prompt || ''}`;
if (textToInspect.trim().length > 0 && base.scenes.length === 0) {
  const hasGlobalFlashback = flashbackRegex.test(textToInspect);
  for (const deadCode of deadCharacters) {
    if (new RegExp(`\\b${deadCode}\\b`, 'i').test(textToInspect) && !hasGlobalFlashback) {
      deterministicViolations.push({ type: 'STATUS_VIOLATION', severity: 'CRITICAL', description: `Deterministic Guard: Dead character ${deadCode} referenced in script/prompt without flashback context.`, entities_involved: [deadCode], suggested_fix: `Ensure ${deadCode} is only depicted in flashbacks.` });
    }
  }
}

return {
  json: {
    ...base, season_no: resolvedSeason, season_number: resolvedSeason,
    hydrated_sources: { story_bible: storyBible, canon_facts: canonFacts, latest_snapshot: latestSnapshot, character_status: charStatuses, story_timeline: timelineEvents, story_rules: storyRules, mystery_tracker: mysteries },
    dead_characters: Array.from(deadCharacters), last_known_locations: lastLocationByChar,
    deterministic_violations: deterministicViolations, has_deterministic_critical: deterministicViolations.some(v => v.severity === 'CRITICAL')
  }
};

const ctx = $('Context Assembly & Continuity Prompt Constructor').first().json;
const llmRaw = $input.item.json || {};

const VALID_TYPES = new Set(['CANON_CONTRADICTION', 'KNOWLEDGE_LEAK', 'STATUS_VIOLATION', 'POWER_LIMIT']);
const VALID_SEVERITIES = new Set(['CRITICAL', 'WARNING', 'INFO']);

let parsedLlm = null;
try {
  const rawText = llmRaw?.choices?.[0]?.message?.content;
  if (rawText) {
    const cleanStr = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
    parsedLlm = JSON.parse(cleanStr);
  }
} catch (e) { parsedLlm = null; }

const llmViolations = Array.isArray(parsedLlm?.violations) ? parsedLlm.violations : [];
const mergedViolations = [...(ctx.deterministic_violations || [])];

for (const v of llmViolations) {
  if (!v || !v.description) continue;
  const normType = VALID_TYPES.has(v.type) ? v.type : 'CANON_CONTRADICTION';
  const normSeverity = VALID_SEVERITIES.has(v.severity) ? v.severity : 'WARNING';
  const isDuplicate = mergedViolations.some(existing => existing.type === normType && existing.description.toLowerCase() === v.description.toString().toLowerCase());
  if (!isDuplicate) {
    mergedViolations.push({ type: normType, severity: normSeverity, description: v.description.toString(), entities_involved: Array.isArray(v.entities_involved) ? v.entities_involved : [], suggested_fix: (v.suggested_fix || 'Align scene with active Story Bible and Canon Facts.').toString() });
  }
}

const criticalCount = mergedViolations.filter(v => v.severity === 'CRITICAL').length;
const warningCount = mergedViolations.filter(v => v.severity === 'WARNING').length;

let rawScore = typeof parsedLlm?.continuity_score === 'number' ? Number(parsedLlm.continuity_score) : 100;
const maxAllowedByPenalties = Math.max(0, 100 - (criticalCount * 35) - (warningCount * 10));
const continuity_score = Math.max(0, Math.min(100, Math.min(rawScore, maxAllowedByPenalties)));

let gate_status = 'PASSED';
if (criticalCount > 0 || continuity_score < 70) { gate_status = 'BLOCKED_CRITICAL'; }
else if (continuity_score >= 90) { gate_status = 'PASSED'; }
else { gate_status = 'WARNINGS_RESOLVED'; }

const can_proceed = gate_status !== 'BLOCKED_CRITICAL';

const recommendedPatches = {
  ...(parsedLlm?.recommended_context_patches || {}),
  dead_characters_prohibited_in_present: ctx.dead_characters || [],
  last_known_locations: ctx.last_known_locations || {},
  auto_corrections: mergedViolations.filter(v => v.severity !== 'CRITICAL').map(v => v.suggested_fix)
};

const continuitySummary = parsedLlm?.continuity_summary || (
  gate_status === 'PASSED' ? `Continuity check 100% clean hai (Score: ${continuity_score}/100). Koi canon ya character status violation nahi mila.` :
  gate_status === 'WARNINGS_RESOLVED' ? `Continuity check minor warnings ke sath pass hua (Score: ${continuity_score}/100). Auto-corrections downstream WF-02 ke liye attach kar diye gaye hain.` :
  `CRITICAL Continuity Violation detect hua hai (Score: ${continuity_score}/100)! Execution ko safely block kar diya gaya hai.`
);

return { json: { ...ctx, continuity_score, status: gate_status, gate_status, can_proceed, violations: mergedViolations, violations_count: { total: mergedViolations.length, critical: criticalCount, warning: warningCount }, continuity_summary: continuitySummary, recommended_context_patches: recommendedPatches } };

let triggerCtx = {};
try { triggerCtx = $('When Executed by Another Workflow').first().json || {}; } catch (e) { triggerCtx = $input.first().json || {}; }
let state = {};
try { state = $('Continuity Score & Decision Engine').first().json || {}; } catch (e) { state = $input.first().json || {}; }

const badge = state.gate_status === 'PASSED' ? '✅ PASSED' : state.gate_status === 'WARNINGS_RESOLVED' ? '⚠️ WARNINGS_RESOLVED' : '🛑 BLOCKED_CRITICAL';
const msg = [`🛡️ **WF-06 Continuity Report**`, `📊 **Score:** ${state.continuity_score ?? 100}/100 | **Gate:** ${badge}`, `💬 **Summary:** ${state.continuity_summary || 'Continuity check completed.'}`].join('\n');
const basePrompt = state.user_prompt || triggerCtx.user_prompt || triggerCtx.userPrompt || '';
const patchedUserPrompt = state.can_proceed && Array.isArray(state.violations) && state.violations.length > 0
  ? `${basePrompt}\n\n[PATCHES]: ${JSON.stringify(state.recommended_context_patches || {})}` : basePrompt;

return {
  json: {
    ...triggerCtx, user_infrastructure: state.user_infrastructure || triggerCtx.user_infrastructure || {}, project_style: state.project_style || triggerCtx.project_style || { visual_style: 'ANIME' },
    project_id: state.project_id || triggerCtx.project_id, project_name: state.project_name || triggerCtx.project_name || 'Active Anime Project',
    episode_no: state.episode_no || triggerCtx.episode_no || 1, episode_number: state.episode_no || triggerCtx.episode_number || 1,
    season_no: state.season_no || triggerCtx.season_no || 1, season_number: state.season_no || triggerCtx.season_number || 1,
    mode: state.mode || triggerCtx.mode || 'SAVE', sessionId: state.sessionId || triggerCtx.sessionId, intent: triggerCtx.intent || state.intent || 'CHECK_CONTINUITY',
    downstream_command: triggerCtx.downstream_command || state.downstream_command || 'CHECK_CONTINUITY', target_workflow_id: state.target_workflow_id || triggerCtx.target_workflow_id || $env.WF_02_STORY_ID || null,
    preflight_workflow_ids: state.preflight_workflow_ids || triggerCtx.preflight_workflow_ids || {}, extracted_params: state.extracted_params || triggerCtx.extracted_params || { episode_number: state.episode_no || 1 },
    user_prompt: patchedUserPrompt, userPrompt: patchedUserPrompt, rawText: state.rawText || patchedUserPrompt, ok: state.can_proceed !== undefined ? state.can_proceed : true,
    workflow_name: 'WF-06', execution_id: $execution.id, continuity_score: state.continuity_score ?? 100, status: state.gate_status || 'PASSED', gate_status: state.gate_status || 'PASSED',
    can_proceed: state.can_proceed !== undefined ? state.can_proceed : true, violations: state.violations || [], violations_count: state.violations_count || 0,
    continuity_summary: state.continuity_summary || '', recommended_context_patches: state.recommended_context_patches || {}, output: msg, text: msg
  }
};

